INSERT INTO "cv_entries" ("id", "section", "title", "organization", "location", "from", "to", "tech", "bullets", "links") VALUES
	('mbition', 'experience', 'Senior Full Stack Engineer', 'MBition GmbH (Mercedes-Benz)', 'Berlin', '2023-10', '', '{"TypeScript","Vue","Nuxt","NestJS","Python","FastAPI","LLMs","Model Context Protocol (MCP)","Kubernetes","PostgreSQL","MongoDB"}', '[{"id":"sdp","text":"Built SDP, a no-code platform for configuring and deploying Mercedes-Benz speech applications, and ship features on it end-to-end in Vue and Nuxt with strict TypeScript, zod-validated REST contracts, and realtime updates over WebSockets"},{"id":"agent-platform","text":"Own the Python platform that hosts our LLM agents on Kubernetes, providing the shared FastAPI service, base classes, and CI/CD that agent teams build on"},{"id":"async-memory","text":"Cut the platform''s memory use by 75% (4 GB to 1 GB) by re-architecting it from synchronous to fully asynchronous Python, removing the need for multiple worker processes"},{"id":"ci-gitlab","text":"Halved CI/CD runtime by migrating the project from GitHub to GitLab and parallelizing the pipelines; each merge request now spins up its own Kubernetes pod, giving 140 contributors a production-like environment to validate changes in"},{"id":"type-safety","text":"Fixed ~5,000 pre-existing type errors and made the codebase unit-testable by decoupling it with dependency injection and enforcing quality gates in CI (Ruff linting, ty static type checking, and a pytest suite)"},{"id":"monorepo","text":"Cut build times by ~50% by consolidating multiple products into a pnpm monorepo, sharing types end to end and enforcing them in CI"},{"id":"ai-dev","text":"Led AI-assisted development across the team: authored the AGENTS.md instruction set and reusable agent skills, and set up a team wiki in the Open Knowledge Format (OKF) to make organizational knowledge agent-consumable"},{"id":"datatable","text":"Replaced tables hand-built per screen with one fully typed Vue datatable behind every list screen, with server-side pagination, sorting, and configurable filters that compile into a single database query"},{"id":"rbac","text":"Built a Role-Based Access Control (RBAC) system with CASL.js, enforcing one permission definition across both the Nuxt UI and the NestJS API"}]'::jsonb, '[]'::jsonb),
	('dericon', 'experience', 'Frontend Engineer (Working Student)', 'DERICON GmbH', 'Berlin & Frankfurt', '2016-12', '2023-10', '{"Vue","Nuxt","React","Remix","TypeScript","Angular"}', '[{"id":"workflow-builder","text":"Launched a graph-based no-code workflow builder (React/Remix) that let non-technical users model and deploy workflows independently"},{"id":"angular","text":"Delivered new features on an Angular-based frontend, modernizing components and improving performance and accessibility"},{"id":"integrations","text":"Built middleware and UI integrations to bridge legacy systems with modern REST APIs, simplifying data flows and de-risking migrations"}]'::jsonb, '[]'::jsonb),
	('slh', 'experience', 'Full Stack Developer', 'SLH GmbH', 'Schüttorf', '2011-10', '2014-11', '{"JavaScript","ExtJS","REST","PHP","Symfony","MySQL"}', '[{"id":"php-modernization","text":"Modernized a legacy frameset-based PHP application into a modular front-end/back-end architecture, rebuilding the UI with ExtJS on a clean PHP backend"},{"id":"stakeholders","text":"Collaborated with stakeholders to prioritize requirements, deliver new features, and resolve defects quickly"}]'::jsonb, '[]'::jsonb),
	('msc', 'education', 'M.Sc. Applied Computer Science', 'HTW Berlin', '', '2019-10', '2023-10', '{}', '[{"id":"thesis","text":"Thesis: Explorative Analysis of Data from Nanopore-Based DNA Sequencing to Identify Dilution Effects"},{"id":"specialisations","text":"Specialisations: AI, Deep Learning, Data Science, Bioinformatics"},{"id":"grade","text":"Grade: 1.1"},{"id":"exchange","text":"Exchange: NTUST, Taipei"}]'::jsonb, '[{"text":"Read the thesis (PDF)","href":"/christoph-stach-master-thesis.pdf"}]'::jsonb),
	('bsc', 'education', 'B.Sc. Applied Computer Science', 'HTW Berlin', '', '2016-04', '2019-09', '{}', '[{"id":"thesis","text":"Thesis: Style transfer for photos using deep learning"},{"id":"grade","text":"Grade: 1.6"},{"id":"exchange","text":"Exchange: UNINTER, Cuernavaca, Mexico"}]'::jsonb, '[]'::jsonb),
